#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n; ll cost, price;
    if (scanf("%d %lld %lld", &n, &cost, &price) != 3) return 0;
    vector<ll> len(n);
    for (auto &x : len) scanf("%lld", &x);
    ll best = 0, maxLen = *max_element(len.begin(), len.end());
    for (ll sale = 1; sale <= maxLen; sale++) {
        ll per = sale * price, profit = 0;
        for (ll rod : len) {
            ll pieces = rod / sale, rem = rod % sale, gain;
            if (pieces == 0) continue;
            if (rem) gain = pieces * (per - cost);  // every kept piece needs a cut
            else {
                // All pieces need one cut fewer; otherwise keep at most pieces-1.
                ll all = pieces * per - (pieces - 1) * cost;
                ll partial = max(0LL, (pieces - 1) * (per - cost));
                gain = max({0LL, all, partial});
            }
            profit += max(0LL, gain);
        }
        best = max(best, profit);
    }
    printf("%lld\n", best);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); long cost = (long) st.nval;
        st.nextToken(); long price = (long) st.nval;
        long[] len = new long[n];
        long maxLen = 0;
        for (int i = 0; i < n; i++) { st.nextToken(); len[i] = (long) st.nval; maxLen = Math.max(maxLen, len[i]); }
        long best = 0;
        for (long sale = 1; sale <= maxLen; sale++) {
            long per = sale * price, profit = 0;
            for (long rod : len) {
                long pieces = rod / sale, rem = rod % sale, gain;
                if (pieces == 0) continue;
                if (rem != 0) gain = pieces * (per - cost); // every kept piece needs a cut
                else {
                    // All pieces need one cut fewer; otherwise keep at most pieces-1.
                    long all = pieces * per - (pieces - 1) * cost;
                    long partial = Math.max(0, (pieces - 1) * (per - cost));
                    gain = Math.max(0, Math.max(all, partial));
                }
                profit += Math.max(0, gain);
            }
            best = Math.max(best, profit);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var cost, price int64
	fmt.Fscan(in, &n, &cost, &price)
	length := make([]int64, n)
	for i := range length {
		fmt.Fscan(in, &length[i])
	}
	var best int64
	for sale := int64(1); sale <= slices.Max(length); sale++ {
		per, profit := sale*price, int64(0)
		for _, rod := range length {
			pieces, rem := rod/sale, rod%sale
			if pieces == 0 {
				continue
			}
			var gain int64
			if rem != 0 {
				gain = pieces * (per - cost) // every kept piece needs a cut
			} else {
				// All pieces need one cut fewer; otherwise keep at most pieces-1.
				all := pieces*per - (pieces-1)*cost
				partial := max(0, (pieces-1)*(per-cost))
				gain = max(0, all, partial)
			}
			profit += max(0, gain)
		}
		best = max(best, profit)
	}
	fmt.Println(best)
}
